#!/usr/bin/env python3
"""
ActiGrid FINAL Four-Issue Closure
================================

This is the last consolidated reviewer-hardening run. It addresses four open items:

A) Rebuild the COMPLETE MSU/ORNL HGB static + sequential frontier with train-only
   median imputation (no pooled pre-split median), and make HGB early stopping explicit.
B) Expand split sensitivity beyond three partitions:
   - 10 UNIQUE group-disjoint partitions for static/sequential HGB on both datasets.
   - 5 UNIQUE group-disjoint partitions for the shared-backbone DQN comparison.
C) Apply clean / mean-replacement / Gaussian / normal-mimic corruption to BOTH
   static HGB and sequential HGB, with attack recall and early-STOP reporting.
D) Re-run Greedy-VOI with backbone/policy-disjoint training rows:
   - group-disjoint policy-training groups when class-complete separation is feasible;
   - otherwise an explicitly labelled stratified row-disjoint fallback.
   Validation used for backbone early stopping is also separated from policy threshold
   selection when feasible.

No test labels are used to select subsets, acquisition orders, entropy thresholds,
temperatures, or Greedy-VOI thresholds.

Required Kaggle inputs
----------------------
/kaggle/input/datasets/sazidul001x94/power-system-attack-dataset
/kaggle/input/datasets/sazidul001x94/tu-delft-cyber-physical-power-system-cpps

Optional (NOT required)
-----------------------
/kaggle/input/datasets/rejaulislam12/rev-hard

Output
------
/kaggle/working/actigrid/four_issue_closure/
/kaggle/working/actigrid/four_issue_closure.zip
"""
from __future__ import annotations
import os, sys, math, json, shutil, itertools, warnings, base64, zlib, types, gc, random, zipfile
from pathlib import Path
from dataclasses import dataclass
from typing import Dict, List, Tuple, Iterable, Optional

