TU_ROOT = Path(os.environ.get('ACTIGRID_TU_ROOT','/kaggle/input/datasets/sazidul001x94/tu-delft-cyber-physical-power-system-cpps'))
HARDEN_DIR = Path(os.environ.get('ACTIGRID_HARDEN_DIR','/kaggle/input/datasets/rejaulislam12/rev-hard'))  # optional; not used by this standalone run
WORK_ROOT = Path(os.environ.get('ACTIGRID_WORK_DIR','/kaggle/working/actigrid'))
OUT = WORK_ROOT/'four_issue_closure'
CACHE = OUT/'cache'
for p in (OUT,CACHE): p.mkdir(parents=True,exist_ok=True)

