RUN_HGB_10 = os.environ.get('ACTIGRID_RUN_HGB_10','1')=='1'
RUN_DQN_5 = os.environ.get('ACTIGRID_RUN_DQN_5','1')=='1'
RUN_HGB_CORRUPTION = os.environ.get('ACTIGRID_RUN_HGB_CORRUPTION','1')=='1'
RUN_GREEDY_HOLDOUT = os.environ.get('ACTIGRID_RUN_GREEDY_HOLDOUT','1')=='1'
N_HGB_SPLITS = int(os.environ.get('ACTIGRID_HGB_SPLITS','10'))
N_DQN_SPLITS = int(os.environ.get('ACTIGRID_DQN_SPLITS','5'))
DQN_EPISODES = int(os.environ.get('ACTIGRID_DQN_EPISODES','20000'))
GREEDY_SEEDS = [42,123,456]
MODEL_SEED = 4242
LAMBDA = 0.50
BATCH = 2048
