# HGB configuration is explicit. early_stopping=False avoids sklearn's internal
# random 10% row validation split and makes every fit use exactly the designated
# training partition.
HGB_KW = dict(max_iter=250, learning_rate=0.08, max_leaf_nodes=31,
              l2_regularization=1e-4, early_stopping=False)

CANDIDATE_SEEDS = [42,123,456,789,2027,31415,27182,16180,14142,17320,
                   9001,10007,12011,15013,18013,22003,25013,30011,40009,50021]

