def import_base_module():
    os.environ['ACTIGRID_MSU_ROOT']=str(MSU_ROOT)
    os.environ['ACTIGRID_TU_ROOT']=str(TU_ROOT)
    os.environ['ACTIGRID_WORK_DIR']=str(WORK_ROOT)
