def run_hgb_10(base,template,raw_msu,seeds):
    all_static=[]; all_seq=[]; all_match=[]; all_corr=[]; meta=[]
    for k,seed in enumerate(seeds,1):
        done=OUT/f'{template.name}_split{seed}_HGB_DONE.csv'
        if done.exists() and not FORCE:
            all_static.append(pd.read_csv(OUT/f'{template.name}_split{seed}_static_corrected.csv'))
            all_seq.append(pd.read_csv(OUT/f'{template.name}_split{seed}_sequential_corrected.csv'))
            all_match.append(pd.read_csv(OUT/f'{template.name}_split{seed}_matched_corrected.csv'))
            cp=OUT/f'{template.name}_split{seed}_HGB_corruption.csv'
            if cp.exists(): all_corr.append(pd.read_csv(cp))
            continue
        print('\n'+'='*100); print(f'HGB CORRECTED FRONTIER {template.name} split {k}/{len(seeds)} seed={seed}'); print('='*100)
        b,s=corrected_split(base,template,raw_msu,seed); cal,sel,unit,over=validation_holdout(b,s.val_idx,seed)
        static,temps,models,probs=fit_hgb_subsets(b,s,seed,cal,sel)
        seq=evaluate_seq(b,s,seed,sel,probs,'calibrated'); match=matched_budget(static,seq)
        static['validation_holdout_unit']=unit; static['validation_group_overlap']=over; seq['validation_holdout_unit']=unit; seq['validation_group_overlap']=over
        static.to_csv(OUT/f'{b.name}_split{seed}_static_corrected.csv',index=False); seq.to_csv(OUT/f'{b.name}_split{seed}_sequential_corrected.csv',index=False); match.to_csv(OUT/f'{b.name}_split{seed}_matched_corrected.csv',index=False); temps.to_csv(OUT/f'{b.name}_split{seed}_temperatures_corrected.csv',index=False)
        corr=hgb_corruption_audit(b,s,seed,static,seq,models,temps) if RUN_HGB_CORRUPTION else pd.DataFrame()
        if len(corr): corr.to_csv(OUT/f'{b.name}_split{seed}_HGB_corruption.csv',index=False); all_corr.append(corr)
        pd.DataFrame([{'done':1,'seed':seed}]).to_csv(done,index=False)
        all_static.append(static); all_seq.append(seq); all_match.append(match); gc.collect()
    S=pd.concat(all_static,ignore_index=True); Q=pd.concat(all_seq,ignore_index=True); M=pd.concat(all_match,ignore_index=True)
    S.to_csv(OUT/f'{template.name}_10split_static_corrected_ALL.csv',index=False); Q.to_csv(OUT/f'{template.name}_10split_sequential_corrected_ALL.csv',index=False); M.to_csv(OUT/f'{template.name}_10split_matched_corrected_ALL.csv',index=False)
    # Per-budget aggregate
    A=M.groupby(['dataset','budget'],as_index=False).agg(static_f1_mean=('static_test_f1','mean'),static_f1_sd=('static_test_f1','std'),seq_f1_mean=('seq_test_f1','mean'),seq_f1_sd=('seq_test_f1','std'),seq_cost_mean=('seq_test_cost','mean'),delta_f1_mean=('delta_f1_seq_minus_static','mean'),delta_f1_sd=('delta_f1_seq_minus_static','std'),n_splits=('split_seed','nunique'))
    A.to_csv(OUT/f'{template.name}_10split_matched_corrected_SUMMARY.csv',index=False)
    if all_corr:
        C=pd.concat(all_corr,ignore_index=True); C.to_csv(OUT/f'{template.name}_10split_HGB_corruption_ALL.csv',index=False)
        CA=C.groupby(['dataset','method','corruption','is_first'],dropna=False,as_index=False).agg(macro_f1_mean=('macro_f1','mean'),macro_f1_sd=('macro_f1','std'),cost_mean=('cost','mean'),attack_detection_recall_mean=('attack_detection_recall','mean'),attack_exact_recall_mean=('attack_exact_recall','mean'),early_stop_attack_mean=('early_stop_rate_attack','mean'),n=('split_seed','nunique'))
        CA.to_csv(OUT/f'{template.name}_10split_HGB_corruption_SUMMARY.csv',index=False)
    return A

