def run_dqn_5(base,template,raw_msu,seeds):
    out=OUT/f'{template.name}_5split_DQN_expansion.csv'
    rows=[]
    for k,seed in enumerate(seeds,1):
        part=OUT/f'{template.name}_DQN_split{seed}.csv'
        if part.exists() and not FORCE: rows.append(pd.read_csv(part)); continue
        print('\n'+'='*100); print(f'DQN PARTITION EXPANSION {template.name} {k}/{len(seeds)} seed={seed}'); print('='*100)
        b,s=corrected_split(base,template,raw_msu,seed); set_seed(base,MODEL_SEED); old=base.CFG.acquisition_lambda; base.CFG.acquisition_lambda=LAMBDA
        fusion=base.train_fusion_classifier(b,s,model_tag=f'closure_split{seed}')
        env=base.ActiveEvidenceEnv(fusion,s.X_scaled,b.y,list(b.X),b.modality_costs,b.label_names,base.CFG.device); base._attach_groups_to_env(env,b)
        pol=base.train_dqn_policy(env,s.train_idx,episodes=DQN_EPISODES,tag=f'closure_{b.name}_{seed}')
        sv,_=base.evaluate_dqn_detailed(env,pol,s.val_idx,'DQN-val'); st,_=base.evaluate_dqn_detailed(env,pol,s.test_idx,'DQN')
        # Same-backbone entropy baseline matched to DQN validation cost.
        vc=base._build_all_mask_cache(fusion,b,s,s.val_idx); tc=base._build_all_mask_cache(fusion,b,s,s.test_idx)
        cand,best=base._search_fixed_order_entropy(b,vc,tc,float(sv.iloc[0].normalized_cost),MODEL_SEED)
        fy,fp,_,_=base.evaluate_classifier(fusion,s.X_scaled,b.y,s.test_idx,list(b.X),'full')
        r=pd.DataFrame([
            {'dataset':b.name,'split_seed':seed,'method':'DQN','macro_f1':float(st.iloc[0].macro_f1),'cost':float(st.iloc[0].normalized_cost)},
            {'dataset':b.name,'split_seed':seed,'method':'OrderEntropy','macro_f1':float(best.test_macro_f1),'cost':float(best.test_cost)},
            {'dataset':b.name,'split_seed':seed,'method':'FullFusion','macro_f1':float(f1_score(fy,fp,average='macro',zero_division=0)),'cost':1.0},
        ])
        r.to_csv(part,index=False); rows.append(r); base.CFG.acquisition_lambda=old; del fusion,pol,env; gc.collect();
        if torch.cuda.is_available(): torch.cuda.empty_cache()
    D=pd.concat(rows,ignore_index=True); D.to_csv(out,index=False)
    A=D.groupby(['dataset','method'],as_index=False).agg(macro_f1_mean=('macro_f1','mean'),macro_f1_sd=('macro_f1','std'),cost_mean=('cost','mean'),cost_sd=('cost','std'),n_splits=('split_seed','nunique'))
    A.to_csv(OUT/f'{template.name}_5split_DQN_expansion_SUMMARY.csv',index=False); return A

# -----------------------------------------------------------------------------
# Greedy-VOI holdout control
# -----------------------------------------------------------------------------
def train_policy_holdout(bundle,train_idx,seed,frac=.70):
    train_idx=np.asarray(train_idx,int); groups=np.asarray(bundle.groups).astype(str); classes=set(np.unique(bundle.y[train_idx])); ug=np.unique(groups[train_idx]); rng=np.random.default_rng(53000+seed)
    support=[]
    for c in sorted(classes): support.append(len(np.unique(groups[train_idx[bundle.y[train_idx]==c]])))
    feasible=min(support)>=2
    if feasible:
        for _ in range(5000):
            perm=rng.permutation(ug); n=max(1,min(len(ug)-1,int(round(len(ug)*frac)))); gb=set(perm[:n]); mask=np.array([g in gb for g in groups[train_idx]]); a,b=train_idx[mask],train_idx[~mask]
            if set(np.unique(bundle.y[a]))==classes and set(np.unique(bundle.y[b]))==classes: return a,b,'group',0
    sss=StratifiedShuffleSplit(n_splits=1,train_size=frac,random_state=53000+seed); a,b=next(sss.split(np.zeros(len(train_idx)),bundle.y[train_idx])); ai,bi=train_idx[a],train_idx[b]
    return ai,bi,'row',len(set(groups[ai])&set(groups[bi]))

def int_mask(x,M): return np.array([(x>>j)&1 for j in range(M)],np.float32)

@torch.no_grad()
def infer_mask(model,split,mods,idx,mi,device):
    idx=np.asarray(idx,int); maskv=int_mask(mi,len(mods)); pp=[]
    for s in range(0,len(idx),BATCH):
        ii=idx[s:s+BATCH]; xs=[torch.from_numpy(split.X_scaled[m][ii]).float().to(device) for m in mods]; mask=torch.from_numpy(np.repeat(maskv[None,:],len(ii),0)).float().to(device); logits,_=model(xs,mask); p=torch.softmax(logits,1).cpu().numpy(); pp.append(p)
    p=np.concatenate(pp); return {'probs':p,'entropy':entropy(p),'pred':p.argmax(1)}

def pre_masks(model,split,mods,idx,device): return {mi:infer_mask(model,split,mods,idx,mi,device) for mi in range(1<<len(mods))}

def fit_voi(pre,mods,costs):
    regs={}; M=len(mods)
    for a,mod in enumerate(mods):
        Xs=[]; ys=[]
        for mi in range(1<<M):
            if (mi>>a)&1: continue
            cur,nxt=pre[mi],pre[mi|(1<<a)]; mv=np.repeat(int_mask(mi,M)[None,:],len(cur['entropy']),0); X=np.concatenate([cur['probs'],cur['entropy'][:,None],mv],1); y=(cur['entropy']-nxt['entropy'])/max(costs[mod],1e-8); Xs.append(X.astype(np.float32)); ys.append(y.astype(np.float32))
        reg=HistGradientBoostingRegressor(max_iter=120,learning_rate=.06,max_leaf_nodes=15,l2_regularization=1e-3,early_stopping=False,random_state=1000+a); reg.fit(np.concatenate(Xs),np.concatenate(ys)); regs[a]=reg
    return regs

def greedy_trace(pre,y,idx,regs,mods,costs,thr):
    M=len(mods); full=(1<<M)-1; rows=[]
    for r,sample in enumerate(idx):
        mi=0;c=0.;steps=0;path=[]
        while True:
            cur=pre[mi]; ent=float(cur['entropy'][r]); pred=int(cur['pred'][r])
            if mi!=0 and (ent<=thr or mi==full): break
            mv=int_mask(mi,M); feat=np.concatenate([cur['probs'][r],[ent],mv])[None,:]; scores=[]
            for a,m in enumerate(mods):
                if (mi>>a)&1: continue
                scores.append((float(regs[a].predict(feat)[0]),a,m))
            scores.sort(key=lambda x:(-x[0],x[1])); _,a,m=scores[0]; mi|=1<<a;c+=costs[m];steps+=1;path.append(m)
        rows.append((int(sample),int(y[r]),pred,c,steps,'>'.join(path)))
    return pd.DataFrame(rows,columns=['sample_idx','y_true','y_pred','cost','steps','path'])

def run_greedy_holdout(base,template,raw_msu):
    rows=[]; primary_seed=42
    # primary partition fixed; stochastic training seeds vary.
    idxsplit=base.group_split(template,seed=primary_seed)
    for seed in GREEDY_SEEDS:
        part=OUT/f'{template.name}_GreedyVOI_holdout_seed{seed}.csv'
        if part.exists() and not FORCE: rows.append(pd.read_csv(part)); continue
        # Determine backbone vs VOI-training rows first. For MSU, imputation/scaling are fitted only on backbone rows.
        bb_idx,voi_idx,unit,over=train_policy_holdout(template,idxsplit.train_idx,seed)
        if template.name.startswith('MSU_'):
            X,_=impute_from_indices(raw_msu.X,bb_idx); b=bundle_with_X(base,template,X)
        else: b=template
        model_val,select_val,vunit,vover=validation_holdout(b,idxsplit.val_idx,9000+seed)
        s=scale_existing_indices(base,b,bb_idx,model_val,idxsplit.test_idx)
        set_seed(base,seed); fusion=base.train_fusion_classifier(b,s,train_idx_override=bb_idx,val_idx_override=model_val,model_tag=f'greedy_holdout_{b.name}_{seed}')
        mods=list(b.X); pre_train=pre_masks(fusion,s,mods,voi_idx,base.CFG.device); regs=fit_voi(pre_train,mods,b.modality_costs); pre_val=pre_masks(fusion,s,mods,select_val,base.CFG.device); pre_test=pre_masks(fusion,s,mods,idxsplit.test_idx,base.CFG.device)
        vals=np.concatenate([pre_val[mi]['entropy'] for mi in range(1,1<<len(mods))]); ths=np.unique(np.r_[-1.0,np.quantile(vals,np.linspace(.05,.95,17)),vals.max()+1])
        curve=[]
        for th in ths:
            va=greedy_trace(pre_val,b.y[select_val],select_val,regs,mods,b.modality_costs,float(th)); te=greedy_trace(pre_test,b.y[idxsplit.test_idx],idxsplit.test_idx,regs,mods,b.modality_costs,float(th)); curve.append({'threshold':th,'val_f1':f1_score(va.y_true,va.y_pred,average='macro',zero_division=0),'val_cost':va.cost.mean(),'test_f1':f1_score(te.y_true,te.y_pred,average='macro',zero_division=0),'test_cost':te.cost.mean()})
        c=pd.DataFrame(curve); c['pareto']=pareto_mask(c.val_cost,c.val_f1); best=c[c.pareto].sort_values(['val_f1','val_cost'],ascending=[False,True]).iloc[0]
        r=pd.DataFrame([{'dataset':b.name,'seed':seed,'backbone_policy_holdout_unit':unit,'backbone_policy_group_overlap':over,'validation_holdout_unit':vunit,'validation_group_overlap':vover,'backbone_rows':len(bb_idx),'voi_train_rows':len(voi_idx),'test_macro_f1':best.test_f1,'test_cost':best.test_cost,'threshold':best.threshold}]); r.to_csv(part,index=False); c.to_csv(OUT/f'{b.name}_GreedyVOI_holdout_seed{seed}_frontier.csv',index=False); rows.append(r)
        del fusion,regs,pre_train,pre_val,pre_test; gc.collect();
        if torch.cuda.is_available(): torch.cuda.empty_cache()
    R=pd.concat(rows,ignore_index=True); R.to_csv(OUT/f'{template.name}_GreedyVOI_holdout_ALL.csv',index=False)
    A=R.groupby('dataset',as_index=False).agg(test_macro_f1_mean=('test_macro_f1','mean'),test_macro_f1_sd=('test_macro_f1','std'),test_cost_mean=('test_cost','mean'),test_cost_sd=('test_cost','std'),n=('seed','count')); A.to_csv(OUT/f'{template.name}_GreedyVOI_holdout_SUMMARY.csv',index=False); return A

