def write_report(results):
    lines=['# ActiGrid Four-Issue Closure','',
           'This report is generated only from the new closure run. It does not claim equivalence.','',
           '## Protocol changes','',
           '- MSU/ORNL: median imputation is fit on the training partition separately for every split.','- HGB: early_stopping=False; no internal random validation fraction is used.','- Static and sequential HGB: 10 unique group-disjoint partitions.','- DQN repeated-split control: 5 unique group-disjoint partitions, fixed model seed 4242 and lambda=0.5.','- HGB corruption: clean, train-mean replacement, Gaussian noise at 2 train SD, and normal-class mimicry.','- Greedy-VOI: VOI regressors are fit only on rows excluded from fusion-backbone fitting.','']
    for key,df in results.items():
        lines += [f'## {key}','```',df.to_string(index=False),'```','']
    (OUT/'FOUR_ISSUE_CLOSURE_SUMMARY.md').write_text('\n'.join(lines))

def main():
    validate_inputs(); base=import_base_module(); base.CFG.final_multiseed_dqn_episodes=DQN_EPISODES; base.CFG.acquisition_lambda=LAMBDA
    tu=load_template_bundle(base,'tu'); msu=load_template_bundle(base,'msu'); raw=load_msu_raw_no_impute(base); verify_msu(msu,raw)
    tu_seeds=unique_split_seeds(base,tu,None,max(N_HGB_SPLITS,N_DQN_SPLITS)); msu_seeds=unique_split_seeds(base,msu,raw,max(N_HGB_SPLITS,N_DQN_SPLITS))
    pd.DataFrame({'rank':range(1,len(tu_seeds)+1),'TU_seed':tu_seeds,'MSU_seed':msu_seeds}).to_csv(OUT/'SELECTED_UNIQUE_PARTITIONS.csv',index=False)
    results={}
    if RUN_HGB_10:
        results['TU 10-split corrected HGB matched-budget']=run_hgb_10(base,tu,None,tu_seeds[:N_HGB_SPLITS])
        results['MSU 10-split corrected HGB matched-budget']=run_hgb_10(base,msu,raw,msu_seeds[:N_HGB_SPLITS])
    if RUN_DQN_5:
        results['TU 5-split DQN expansion']=run_dqn_5(base,tu,None,tu_seeds[:N_DQN_SPLITS])
        results['MSU 5-split corrected DQN expansion']=run_dqn_5(base,msu,raw,msu_seeds[:N_DQN_SPLITS])
    if RUN_GREEDY_HOLDOUT:
        results['TU Greedy-VOI holdout']=run_greedy_holdout(base,tu,None)
        results['MSU Greedy-VOI holdout']=run_greedy_holdout(base,msu,raw)
    write_report(results)
    manifest={'hgb_splits':N_HGB_SPLITS,'dqn_splits':N_DQN_SPLITS,'dqn_episodes':DQN_EPISODES,'tu_split_seeds':tu_seeds[:N_HGB_SPLITS],'msu_split_seeds':msu_seeds[:N_HGB_SPLITS],
              'hgb_config':HGB_KW,'msu_imputation':'train-partition median per split','greedy_voi':'backbone/policy holdout','hgb_corruption':RUN_HGB_CORRUPTION}
    (OUT/'run_manifest.json').write_text(json.dumps(manifest,indent=2))
    zp=WORK_ROOT/'four_issue_closure.zip'
    if zp.exists(): zp.unlink()
    shutil.make_archive(str(zp.with_suffix('')),'zip',OUT)
    print('\n'+'='*100); print('FOUR-ISSUE CLOSURE COMPLETE'); print('Output:',OUT); print('ZIP:',zp); print('='*100)



# =============================================================================
# MULTI-SESSION PERSISTENT CHECKPOINT RUNNER
# =============================================================================
# Why this exists:
# Kaggle /kaggle/working is ephemeral across new sessions. The original
# monolithic run could therefore lose many hours after a 12-hour timeout.
#
# This runner:
#   1) restores a checkpoint ZIP supplied as a Kaggle input, if present;
#   2) automatically detects the next bounded phase;
#   3) runs only that phase;
#   4) writes a portable checkpoint ZIP for the next session;
#   5) on the final phase, writes the final results ZIP.
#
# No phase number needs to be edited manually.

CHECKPOINT_NAME = "actigrid_four_issue_checkpoint.zip"
# Release change: ACTIGRID_ZIP_DIR lets the run write its ZIPs outside Kaggle.
ZIP_DIR = Path(os.environ.get("ACTIGRID_ZIP_DIR", "/kaggle/working"))
CHECKPOINT_OUT = ZIP_DIR / CHECKPOINT_NAME
FINAL_OUT = ZIP_DIR / "four_issue_closure_FINAL.zip"
STATE_PATH = OUT / "MULTISESSION_STATE.json"
SEEDS_PATH = OUT / "MULTISESSION_SEEDS.json"

PHASES = [
    "01_TU_HGB_10",
    "02_MSU_HGB_1_3",
    "03_MSU_HGB_4_6",
    "04_MSU_HGB_7_10",
    "05_DQN_TU_5_AND_MSU_1_2",
    "06_DQN_MSU_3_5_GREEDY_AND_FINAL",
]

def _checkpoint_candidates():
    """Find a portable checkpoint attached through Kaggle input."""
    env = os.environ.get("ACTIGRID_CHECKPOINT_ZIP", "").strip()
    out = []
    if env:
        p = Path(env)
        if p.exists():
            out.append(p)

    root = Path("/kaggle/input")
    if root.exists():
        # Exact preferred name first.
        out.extend(root.rglob(CHECKPOINT_NAME))
        # Accept renamed copies/dataset packaging.
        for p in root.rglob("*.zip"):
            low = p.name.lower()
            if "four_issue" in low and "checkpoint" in low and p not in out:
                out.append(p)
    # deterministic, unique
    uniq = []
    seen = set()
    for p in out:
        s = str(p)
        if s not in seen:
            seen.add(s)
            uniq.append(p)
    return uniq

def restore_portable_checkpoint():
    """
    Restore checkpoint into OUT.

    Archive members are relative to OUT, so this never writes into /kaggle/input.
    If OUT already contains state (same live session), no restore is needed.
    """
    if STATE_PATH.exists():
        print("[checkpoint] live working state already present:", STATE_PATH)
        return None

    cands = _checkpoint_candidates()
    if not cands:
        print("[checkpoint] no prior portable checkpoint attached; starting from phase 1")
        return None

    cp = cands[0]
    print("[checkpoint] restoring:", cp)
    OUT.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(cp, "r") as z:
        z.extractall(OUT)
    print("[checkpoint] restore complete")
    return cp

def _checkpoint_include(path: Path) -> bool:
    """
    Keep result CSV/JSON/MD files and the three reusable dataset caches.
    Exclude hundreds of fitted subset-HGB joblib files; completed HGB splits
    are resumed from their DONE marker + CSV outputs and do not require models.
    """
    rel = path.relative_to(OUT)
    parts = rel.parts
    if not parts:
        return False

    if parts[0] != "cache":
        return True

    # Only top-level reusable bundle/raw caches.
    if len(parts) == 2 and path.name in {
        "tu_template_bundle.joblib",
        "msu_template_bundle.joblib",
        "msu_raw_no_impute.joblib",
    }:
        return True
    return False

def export_portable_checkpoint():
    """Create a portable checkpoint ZIP that can be attached to the next session."""
    tmp = CHECKPOINT_OUT.with_suffix(".tmp.zip")
    if tmp.exists():
        tmp.unlink()
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED, allowZip64=True) as z:
        for p in OUT.rglob("*"):
            if p.is_file() and _checkpoint_include(p):
                z.write(p, arcname=str(p.relative_to(OUT)))
    if CHECKPOINT_OUT.exists():
        CHECKPOINT_OUT.unlink()
    tmp.replace(CHECKPOINT_OUT)
    print(f"[checkpoint] exported: {CHECKPOINT_OUT}")
    print(f"[checkpoint] size MB: {CHECKPOINT_OUT.stat().st_size/1024/1024:.2f}")
    return CHECKPOINT_OUT

def export_final_results():
    """Final archive excludes transient HGB model caches."""
    tmp = FINAL_OUT.with_suffix(".tmp.zip")
    if tmp.exists():
        tmp.unlink()
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED, allowZip64=True) as z:
        for p in OUT.rglob("*"):
            if p.is_file() and _checkpoint_include(p):
                z.write(p, arcname=str(p.relative_to(OUT)))
    if FINAL_OUT.exists():
        FINAL_OUT.unlink()
    tmp.replace(FINAL_OUT)
    print(f"[final] exported: {FINAL_OUT}")
    print(f"[final] size MB: {FINAL_OUT.stat().st_size/1024/1024:.2f}")
    return FINAL_OUT

def load_state():
    if STATE_PATH.exists():
        try:
            return json.loads(STATE_PATH.read_text())
        except Exception:
            pass
    return {
        "format_version": 1,
        "completed_phases": [],
        "current_phase": None,
        "finished": False,
    }

def save_state(state):
    STATE_PATH.write_text(json.dumps(state, indent=2))

def mark_phase_started(state, phase):
    state["current_phase"] = phase
    save_state(state)

def mark_phase_complete(state, phase):
    done = list(state.get("completed_phases", []))
    if phase not in done:
        done.append(phase)
    state["completed_phases"] = done
    state["current_phase"] = None
    state["finished"] = len(done) == len(PHASES)
    save_state(state)

def next_phase(state):
    done = set(state.get("completed_phases", []))
    for p in PHASES:
        if p not in done:
            return p
    return None

def _load_or_create_seed_plan(base):
    if SEEDS_PATH.exists():
        d = json.loads(SEEDS_PATH.read_text())
        return list(map(int, d["tu_seeds"])), list(map(int, d["msu_seeds"]))

    print("[seed-plan] selecting 10 unique group-disjoint partitions per dataset")
    tu = load_template_bundle(base, "tu")
    msu = load_template_bundle(base, "msu")
    raw = load_msu_raw_no_impute(base)
    verify_msu(msu, raw)
    tu_seeds = unique_split_seeds(base, tu, None, 10)
    msu_seeds = unique_split_seeds(base, msu, raw, 10)
    SEEDS_PATH.write_text(json.dumps({
        "tu_seeds": list(map(int, tu_seeds)),
        "msu_seeds": list(map(int, msu_seeds)),
    }, indent=2))
    pd.DataFrame({
        "rank": range(1, 11),
        "TU_seed": tu_seeds,
        "MSU_seed": msu_seeds,
    }).to_csv(OUT / "SELECTED_UNIQUE_PARTITIONS.csv", index=False)
    return tu_seeds, msu_seeds

def _load_tu(base):
    return load_template_bundle(base, "tu")

def _load_msu(base):
    msu = load_template_bundle(base, "msu")
    raw = load_msu_raw_no_impute(base)
    verify_msu(msu, raw)
    return msu, raw

def _aggregate_final(base, tu_seeds, msu_seeds):
    """
    All expensive split-level artifacts already exist at this point.
    Calling the existing functions with the full seed lists only reloads
    completed CSVs and builds the final summaries.
    """
    print("[finalize] rebuilding final aggregate summaries from completed split files")
    tu = _load_tu(base)
    msu, raw = _load_msu(base)

    results = {}
    results["TU 10-split corrected HGB matched-budget"] = run_hgb_10(
        base, tu, None, tu_seeds[:10]
    )
    results["MSU 10-split corrected HGB matched-budget"] = run_hgb_10(
        base, msu, raw, msu_seeds[:10]
    )
    results["TU 5-split DQN expansion"] = run_dqn_5(
        base, tu, None, tu_seeds[:5]
    )
    results["MSU 5-split corrected DQN expansion"] = run_dqn_5(
        base, msu, raw, msu_seeds[:5]
    )
    results["TU Greedy-VOI holdout"] = run_greedy_holdout(base, tu, None)
    results["MSU Greedy-VOI holdout"] = run_greedy_holdout(base, msu, raw)

    write_report(results)
    manifest = {
        "execution_mode": "multi-session persistent checkpoint",
        "hgb_splits": 10,
        "dqn_splits": 5,
        "dqn_episodes": DQN_EPISODES,
        "tu_split_seeds": tu_seeds[:10],
        "msu_split_seeds": msu_seeds[:10],
        "hgb_config": HGB_KW,
        "msu_imputation": "train-partition median per split",
        "greedy_voi": "backbone/policy holdout",
        "hgb_corruption": RUN_HGB_CORRUPTION,
        "phases": PHASES,
    }
    (OUT / "run_manifest.json").write_text(json.dumps(manifest, indent=2))

def multisession_main():
    validate_inputs()
    restore_portable_checkpoint()

    base = import_base_module()
    base.CFG.final_multiseed_dqn_episodes = DQN_EPISODES
    base.CFG.acquisition_lambda = LAMBDA

    state = load_state()
    if state.get("finished", False):
        print("[state] all phases already complete")
        export_portable_checkpoint()
        export_final_results()
        return

    tu_seeds, msu_seeds = _load_or_create_seed_plan(base)
    phase = next_phase(state)

    if phase is None:
        state["finished"] = True
        save_state(state)
        export_portable_checkpoint()
        export_final_results()
        return

    print("\n" + "=" * 100)
    print(f"MULTI-SESSION PHASE: {phase}")
    print(f"Completed before this run: {len(state.get('completed_phases', []))}/{len(PHASES)}")
    print("=" * 100)
    mark_phase_started(state, phase)

    # Each phase is intentionally bounded well below the old monolithic workload.
    if phase == "01_TU_HGB_10":
        tu = _load_tu(base)
        run_hgb_10(base, tu, None, tu_seeds[:10])

    elif phase == "02_MSU_HGB_1_3":
        msu, raw = _load_msu(base)
        run_hgb_10(base, msu, raw, msu_seeds[0:3])

    elif phase == "03_MSU_HGB_4_6":
        msu, raw = _load_msu(base)
        run_hgb_10(base, msu, raw, msu_seeds[3:6])

    elif phase == "04_MSU_HGB_7_10":
        msu, raw = _load_msu(base)
        run_hgb_10(base, msu, raw, msu_seeds[6:10])

    elif phase == "05_DQN_TU_5_AND_MSU_1_2":
        tu = _load_tu(base)
        msu, raw = _load_msu(base)
        run_dqn_5(base, tu, None, tu_seeds[:5])
        run_dqn_5(base, msu, raw, msu_seeds[:2])

    elif phase == "06_DQN_MSU_3_5_GREEDY_AND_FINAL":
        tu = _load_tu(base)
        msu, raw = _load_msu(base)
        run_dqn_5(base, msu, raw, msu_seeds[2:5])
        run_greedy_holdout(base, tu, None)
        run_greedy_holdout(base, msu, raw)

        # Build final summaries from every completed per-split artifact.
        _aggregate_final(base, tu_seeds, msu_seeds)

    else:
        raise RuntimeError(f"Unknown phase: {phase}")

    mark_phase_complete(state, phase)

    # Always export after a successfully bounded phase.
    export_portable_checkpoint()

    print("\n" + "=" * 100)
    print(f"PHASE COMPLETE: {phase}")
    print(f"Checkpoint for next session: {CHECKPOINT_OUT}")
    remaining = [p for p in PHASES if p not in set(load_state().get("completed_phases", []))]
    if remaining:
        print("NEXT PHASE:", remaining[0])
        print("Download the checkpoint ZIP and attach it to the next Kaggle session.")
    else:
        print("ALL PHASES COMPLETE")
        export_final_results()
        print("Final results ZIP:", FINAL_OUT)
    print("=" * 100)



# =============================================================================
# FULL END-TO-END CHECKPOINTED RUNNER
# =============================================================================
#
# One Run All:
#   * restores an attached portable checkpoint if present;
#   * automatically skips already-completed units;
#   * runs all remaining HGB, DQN and Greedy-VOI work;
#   * refreshes the portable checkpoint after every completed split/seed;
#   * performs final aggregation;
#   * writes both the latest checkpoint and final result ZIP.
#
# IMPORTANT:
# /kaggle/working itself is not persistent across a brand-new Kaggle session.
# The portable ZIP is therefore the cross-session artifact. If this run ever
# approaches the session limit, download the latest checkpoint ZIP before
# starting a fresh session.

FULL_STATE_PATH = OUT / "FULL_END_TO_END_STATE.json"

def full_state():
    if FULL_STATE_PATH.exists():
        try:
            return json.loads(FULL_STATE_PATH.read_text())
        except Exception:
            pass
    return {
        "format_version": 1,
        "runner": "full_end_to_end_checkpointed",
        "completed_units": [],
        "finished": False,
    }

def save_full_state(state):
    FULL_STATE_PATH.write_text(json.dumps(state, indent=2))

def record_unit(unit):
    state = full_state()
    done = list(state.get("completed_units", []))
    if unit not in done:
        done.append(unit)
    state["completed_units"] = done
    save_full_state(state)

def checkpoint_after(unit):
    record_unit(unit)
    cp = export_portable_checkpoint()
    print(f"[progress] completed unit: {unit}")
    print(f"[progress] portable checkpoint refreshed: {cp}")
    return cp

def _hgb_done(dataset_name, seed):
    return (OUT / f"{dataset_name}_split{seed}_HGB_DONE.csv").exists()

def _dqn_done(dataset_name, seed):
    return (OUT / f"{dataset_name}_DQN_split{seed}.csv").exists()

def _greedy_done(dataset_name, seed):
    return (OUT / f"{dataset_name}_GreedyVOI_holdout_seed{seed}.csv").exists()

def run_hgb_units(base, template, raw_msu, seeds, label):
    """
    Execute one corrected HGB partition at a time so every completed partition
    becomes independently portable.
    """
    total = len(seeds)
    for i, seed in enumerate(seeds, 1):
        unit = f"HGB::{template.name}::{seed}"
        if _hgb_done(template.name, seed) and not FORCE:
            print(f"[skip] {unit} already completed ({i}/{total})")
            continue
        print("\n" + "#" * 100)
        print(f"FULL RUN | {label} | partition {i}/{total} | seed={seed}")
        print("#" * 100)
        run_hgb_10(base, template, raw_msu, [seed])
        checkpoint_after(unit)

def run_dqn_units(base, template, raw_msu, seeds, label):
    """
    Execute one DQN partition at a time. A finished 20k-episode partition is
    immediately checkpointed before moving to the next one.
    """
    total = len(seeds)
    for i, seed in enumerate(seeds, 1):
        unit = f"DQN::{template.name}::{seed}"
        if _dqn_done(template.name, seed) and not FORCE:
            print(f"[skip] {unit} already completed ({i}/{total})")
            continue
        print("\n" + "#" * 100)
        print(f"FULL RUN | {label} | DQN partition {i}/{total} | seed={seed}")
        print("#" * 100)
        run_dqn_5(base, template, raw_msu, [seed])
        checkpoint_after(unit)

def run_greedy_units(base, template, raw_msu, seeds, label):
    """
    Greedy-VOI is normally implemented as a 3-seed batch. Temporarily narrow
    the global seed list to one seed at a time so each finished seed is made
    portable before the next seed starts.
    """
    global GREEDY_SEEDS
    original = list(GREEDY_SEEDS)
    total = len(seeds)
    try:
        for i, seed in enumerate(seeds, 1):
            unit = f"GREEDY::{template.name}::{seed}"
            if _greedy_done(template.name, seed) and not FORCE:
                print(f"[skip] {unit} already completed ({i}/{total})")
                continue
            print("\n" + "#" * 100)
            print(f"FULL RUN | {label} | Greedy-VOI seed {i}/{total} | seed={seed}")
            print("#" * 100)
            GREEDY_SEEDS = [int(seed)]
            run_greedy_holdout(base, template, raw_msu)
            checkpoint_after(unit)
    finally:
        GREEDY_SEEDS = original

def final_aggregate_full(base, tu, msu, raw, tu_seeds, msu_seeds):
    """Rebuild all aggregate tables from completed split/seed files."""
    global GREEDY_SEEDS
    original = list(GREEDY_SEEDS)
    GREEDY_SEEDS = [42, 123, 456]
    try:
        print("\n" + "=" * 100)
        print("FINAL AGGREGATION — loading all completed split/seed artifacts")
        print("=" * 100)

        results = {}
        results["TU 10-split corrected HGB matched-budget"] = run_hgb_10(
            base, tu, None, tu_seeds[:10]
        )
        results["MSU 10-split corrected HGB matched-budget"] = run_hgb_10(
            base, msu, raw, msu_seeds[:10]
        )
        results["TU 5-split DQN expansion"] = run_dqn_5(
            base, tu, None, tu_seeds[:5]
        )
        results["MSU 5-split corrected DQN expansion"] = run_dqn_5(
            base, msu, raw, msu_seeds[:5]
        )
        results["TU Greedy-VOI holdout"] = run_greedy_holdout(
            base, tu, None
        )
        results["MSU Greedy-VOI holdout"] = run_greedy_holdout(
            base, msu, raw
        )

        write_report(results)

        manifest = {
            "execution_mode": "full end-to-end checkpointed",
            "hgb_splits": 10,
            "dqn_splits": 5,
            "dqn_episodes": DQN_EPISODES,
            "dqn_model_seed": MODEL_SEED,
            "lambda": LAMBDA,
            "tu_split_seeds": list(map(int, tu_seeds[:10])),
            "msu_split_seeds": list(map(int, msu_seeds[:10])),
            "greedy_seeds": [42, 123, 456],
            "hgb_config": HGB_KW,
            "msu_imputation": "train-partition median per split",
            "hgb_corruption": bool(RUN_HGB_CORRUPTION),
            "greedy_voi": "backbone/policy holdout",
            "checkpoint_policy": "after every completed HGB split, DQN split and Greedy seed",
        }
        (OUT / "run_manifest.json").write_text(json.dumps(manifest, indent=2))

        state = full_state()
        state["finished"] = True
        save_full_state(state)

        # Mark old multi-session state finished too, if present, so a later
        # restore cannot mistakenly ask for an obsolete phase.
        old_state = load_state()
        old_state["completed_phases"] = list(PHASES)
        old_state["current_phase"] = None
        old_state["finished"] = True
        save_state(old_state)

        export_portable_checkpoint()
        export_final_results()

        # Also retain the original conventional filename.
        legacy = WORK_ROOT / "four_issue_closure.zip"
        if legacy.exists():
            legacy.unlink()
        shutil.make_archive(str(legacy.with_suffix("")), "zip", OUT)

        print("\n" + "=" * 100)
        print("FULL FOUR-ISSUE CLOSURE COMPLETE")
        print("Results directory :", OUT)
        print("Portable checkpoint:", CHECKPOINT_OUT)
        print("Final ZIP         :", FINAL_OUT)
        print("Legacy ZIP        :", legacy)
        print("=" * 100)
        return results
    finally:
        GREEDY_SEEDS = original

def full_end_to_end_checkpointed_main():
    print("=" * 100)
    print("ActiGrid FULL END-TO-END CHECKPOINTED FOUR-ISSUE CLOSURE")
    print("=" * 100)

    validate_inputs()

    # If a previous checkpoint is attached, restore it before loading state.
    restored = restore_portable_checkpoint()
    if restored is not None:
        print("[resume] restored prior work from:", restored)
    else:
        print("[resume] no portable checkpoint found; beginning from available local state")

    base = import_base_module()
    base.CFG.final_multiseed_dqn_episodes = DQN_EPISODES
    base.CFG.acquisition_lambda = LAMBDA

    # Reuse/create deterministic seed plan.
    tu_seeds, msu_seeds = _load_or_create_seed_plan(base)

    # Load cached template/raw bundles (checkpoint carries these when available).
    tu = _load_tu(base)
    msu, raw = _load_msu(base)

    # Show what can already be skipped.
    print("\nCurrent completion audit")
    print("-" * 100)
    print("TU HGB done :", sum(_hgb_done(tu.name, s) for s in tu_seeds[:10]), "/ 10")
    print("MSU HGB done:", sum(_hgb_done(msu.name, s) for s in msu_seeds[:10]), "/ 10")
    print("TU DQN done :", sum(_dqn_done(tu.name, s) for s in tu_seeds[:5]), "/ 5")
    print("MSU DQN done:", sum(_dqn_done(msu.name, s) for s in msu_seeds[:5]), "/ 5")
    print("TU Greedy   :", sum(_greedy_done(tu.name, s) for s in [42,123,456]), "/ 3")
    print("MSU Greedy  :", sum(_greedy_done(msu.name, s) for s in [42,123,456]), "/ 3")
    print("-" * 100)

    # 1) Corrected static/sequential HGB over 10 unique group-disjoint partitions.
    run_hgb_units(
        base, tu, None, tu_seeds[:10],
        "TU Delft corrected static/sequential HGB + corruption"
    )
    run_hgb_units(
        base, msu, raw, msu_seeds[:10],
        "MSU/ORNL corrected train-only-imputation static/sequential HGB + corruption"
    )

    # 2) Five unique group-disjoint DQN partitions.
    run_dqn_units(
        base, tu, None, tu_seeds[:5],
        "TU Delft five-partition DQN expansion"
    )
    run_dqn_units(
        base, msu, raw, msu_seeds[:5],
        "MSU/ORNL corrected five-partition DQN expansion"
    )

    # 3) Greedy-VOI backbone/policy holdout control.
    run_greedy_units(
        base, tu, None, [42,123,456],
        "TU Delft Greedy-VOI holdout"
    )
    run_greedy_units(
        base, msu, raw, [42,123,456],
        "MSU/ORNL Greedy-VOI holdout"
    )

    # 4) Final aggregate tables/report/archive.
    return final_aggregate_full(
        base, tu, msu, raw, tu_seeds, msu_seeds
    )

if __name__ == "__main__":
    full_end_to_end_checkpointed_main()
